// public BSC RPCs — eth_call / eth_getBalance / eth_getBlockByNumber
const PUBLIC_RPCS = ["https://bsc-dataseed.binance.org", "https://bsc.publicnode.com", "https://bsc.drpc.org"];
// getLogs-capable providers: [url, max block range]
const LOG_RPCS = [["https://bsc-mainnet.public.blastapi.io", null], ["https://bsc.publicnode.com", 4999]];

async function rpcPost(url, method, params, timeoutMs = 8000) {
  const ac = new AbortController();
  const t = setTimeout(() => ac.abort(), timeoutMs);
  try {
    const r = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params }),
      signal: ac.signal,
    });
    const j = await r.json();
    if (j.error) throw new Error(`rpc: ${j.error.message || JSON.stringify(j.error)}`);
    return j.result;
  } finally { clearTimeout(t); }
}

// try Alchemy (if configured), then public RPCs in order
async function rpc(env, method, params) {
  const tried = [];
  if (env && env.ALCHEMY_API_KEY) {
    try { return await rpcPost(`https://bnb-mainnet.g.alchemy.com/v2/${env.ALCHEMY_API_KEY}`, method, params); }
    catch (e) { tried.push(`alchemy: ${e.message}`); }
  }
  for (const u of PUBLIC_RPCS) {
    try { return await rpcPost(u, method, params); }
    catch (e) { tried.push(`${new URL(u).host}: ${e.message}`); }
  }
  throw new Error("all RPCs failed: " + tried.join(" | "));
}

const pad = (addr) => "0x70a08231" + "000000000000000000000000" + addr.toLowerCase().replace(/^0x/, "");

// ---------- price: read the real PancakeSwap V3 FLAPJAX/WBNB 1% pool ----------
async function bnbUsd() {
  try {
    const r = await fetch(`https://api.dexscreener.com/latest/dex/tokens/${WBNB}`, { headers: { "user-agent": "flapjax-desk/2.0" } });
    if (r.ok) {
      const j = await r.json();
      const pairs = (j.pairs || []).filter((p) => p.chainId === "bsc" && p.quoteToken?.symbol === "USDT");
      const best = pairs.sort((a, b) => (b.liquidity?.usd || 0) - (a.liquidity?.usd || 0))[0];
      if (best && best.priceUsd) return { usd: Number(best.priceUsd), source: `dexscreener ${best.dexId}` };
    }
  } catch (_) {}
  return { usd: null, source: "unavailable" };
}

async function poolPrice(env) {
  const [slot0Hex, liqHex, feeHex] = await Promise.all([
    rpc(env, "eth_call", [{ to: POOL, data: "0x3850c7bd" }, "latest"]),  // slot0()
    rpc(env, "eth_call", [{ to: POOL, data: "0x1a686502" }, "latest"]), // liquidity()
    rpc(env, "eth_call", [{ to: POOL, data: "0xddca3f43" }, "latest"]), // fee()
  ]);
  const sqrtX96 = Number(BigInt(slot0Hex.slice(0, 66))); // first 32-byte word = sqrtPriceX96
  const wbnbPerFj = (sqrtX96 / 2 ** 96) ** 2; // token1 (WBNB) per token0 (FLAPJAX), both 18 decimals
  const fee = parseInt(feeHex, 16);
  const liquidity = String(BigInt(liqHex));
  const bnb = await bnbUsd();
  const usdPerFj = bnb.usd != null ? Math.round(wbnbPerFj * bnb.usd * 1e12) / 1e12 : null;
  return {
    wbnb_per_flapjax: wbnbPerFj,
    flapjax_per_wbnb: 1 / wbnbPerFj,
    usd_per_flapjax: usdPerFj,
    bnb_usd: bnb.usd,
    pool: { address: POOL, dex: "PancakeSwap V3", pair: "FLAPJAX/WBNB", fee_bps: fee / 100, liquidity },
    source: "PancakeSwap V3 FLAPJAX/WBNB 1% pool, slot0 read live from BSC (no key, no trust required)",
    bnb_price_source: bnb.source,
  };
}

// ---------- treasury payout transfers ----------
// fast path: Alchemy getAssetTransfers (only when a key is configured AND reachable)
async function transfersAlchemy(env) {
  if (!env.ALCHEMY_API_KEY) throw new Error("no alchemy key");
  const params = {
    fromBlock: "0x0", toBlock: "latest", fromAddress: TREASURY,
    contractAddresses: [FLAPJAX], category: ["erc20"], withMetadata: true,
    maxCount: "0x3e8", order: "desc",
  };
  const out = [];
  let pageKey = null;
  for (let i = 0; i < 5; i++) {
    const p = pageKey ? { ...params, pageKey } : params;
    const res = await rpcPost(`https://bnb-mainnet.g.alchemy.com/v2/${env.ALCHEMY_API_KEY}`, "alchemy_getAssetTransfers", [p]);
    for (const t of (res.transfers || [])) out.push({
      tx_hash: t.hash, block: parseInt(t.blockNum, 16), timestamp_utc: t.metadata?.blockTimestamp,
      to: t.to, amount_flapjax: t.value,
    });
    pageKey = res.pageKey;
    if (!pageKey) break;
  }
  return out;
}

// keyless path: parse raw Transfer logs (address=FLAPJAX, from=treasury, to?)
function parseLog(l) {
  return {
    tx_hash: l.transactionHash, block: parseInt(l.blockNumber, 16),
    to: "0x" + l.topics[2].slice(26), amount_flapjax: Number(BigInt(l.data) / 10n ** 9n) / 1e9,
  };
}

// live delta since the snapshot, anchored at the chain head:
// 1) blastapi: one full-range call (often rate-limited; harmless to try)
// 2) publicnode: recent-window chunks backward from head (its window is small but real)
async function deltaScan(fromBlock, latest) {
  const topics = [TRANSFER_TOPIC, P32(TREASURY)];
  for (let i = 0; i < 2; i++) {
    try {
      const logs = await rpcPost(LOG_RPCS[0][0], "eth_getLogs", [{ address: FLAPJAX, topics, fromBlock: "0x" + fromBlock.toString(16), toBlock: "latest" }], 10000);
      return { logs: logs.map(parseLog), provider: LOG_RPCS[0][0], deltaFrom: fromBlock };
    } catch (e) { if (i === 1) break; await new Promise((r) => setTimeout(r, 250)); }
  }
  const [url, width] = LOG_RPCS[1];
  let logs = [], from = latest;
  while (from > fromBlock) {
    const lo = Math.max(from - width, fromBlock);
    try {
      const chunk = await rpcPost(url, "eth_getLogs", [{ address: FLAPJAX, topics, fromBlock: "0x" + lo.toString(16), toBlock: "0x" + from.toString(16) }]);
      logs.push(...chunk.map(parseLog));
    } catch (e) { break; } // recent-window edge or provider down: keep what we have
    if (lo <= fromBlock) { from = lo; break; }
    from = lo;
    await new Promise((r) => setTimeout(r, 20));
  }
  return { logs, provider: url, deltaFrom: from };
}

// fill in block timestamps for the most recent events lacking one (keyless mode)
async function fillTimestamps(events, cap = 20) {
  const need = events.filter((e) => !e.timestamp_utc).slice(0, cap);
  const uniq = [...new Set(need.map((e) => e.block))];
  for (let i = 0; i < uniq.length; i += 5) {
    await Promise.all(uniq.slice(i, i + 5).map(async (b) => {
      try {
        const blk = await rpc(null, "eth_getBlockByNumber", ["0x" + b.toString(16), false]);
        for (const e of need) if (e.block === b && !e.timestamp_utc) e.timestamp_utc = blk?.timestamp ? new Date(parseInt(blk.timestamp, 16) * 1000).toISOString() : null;
      } catch (_) {}
    }));
  }
}

let CACHE = null; // { at, merged } — in-memory, per-isolate, 10 min
async function transfersKeyless(env, toAddr) {
  const latest = parseInt(await rpc(env, "eth_blockNumber", []), 16);
  const now = Date.now();
  if (!CACHE || now - CACHE.at > 10 * 60 * 1000) {
    const d = await deltaScan(SNAPSHOT_BLOCK, latest);
    const seen = new Set();
    const merged = [
      ...d.logs.map((e) => ({ ...e, timestamp_utc: null })),
      ...SNAPSHOT.map((e) => ({ tx_hash: e.h, block: e.b, to: e.t, amount_flapjax: e.v, timestamp_utc: e.ts })),
    ]
      .filter((e) => (seen.has(e.tx_hash) ? false : (seen.add(e.tx_hash), true)))
      .sort((a, b) => b.block - a.block);
    const contiguous = d.deltaFrom != null && d.deltaFrom <= SNAPSHOT_BLOCK + 1;
    CACHE = { at: now, merged, meta: { delta_provider: d.provider, delta_from_block: d.deltaFrom, snapshot_block: SNAPSHOT_BLOCK, contiguous, latest } };
  }
  const merged = toAddr ? CACHE.merged.filter((e) => e.to.toLowerCase() === toAddr.toLowerCase()) : CACHE.merged;
  return { events: merged, meta: { ...CACHE.meta, latest, source: "baked payout snapshot (on-chain verifiable) + keyless public-RPC live delta" } };
}

async function transfers(env, toAddr) {
  try {
    const events = await transfersAlchemy(env);
    return { events: toAddr ? events.filter((e) => e.to.toLowerCase() === toAddr.toLowerCase()) : events, meta: { source: "alchemy getAssetTransfers", snapshot_block: SNAPSHOT_BLOCK } };
  } catch (e) {
    const r = await transfersKeyless(env, toAddr);
    r.meta.source = r.meta.source + " (alchemy path failed: " + String(e.message).slice(0, 120) + ")";
    return r;
  }
}

async function stats(env) {
  const [supplyHex, treasuryHex, treasuryBnbHex, price, tr] = await Promise.all([
    rpc(env, "eth_call", [{ to: FLAPJAX, data: "0x18160ddd" }, "latest"]),
    rpc(env, "eth_call", [{ to: FLAPJAX, data: pad(TREASURY) }, "latest"]),
    rpc(env, "eth_getBalance", [TREASURY, "latest"]),
    poolPrice(env),
    transfers(env, null),
  ]);
  const treasuryBal = Number(BigInt(treasuryHex) / 10n ** 9n) / 1e9;
  const supply = Number(BigInt(supplyHex) / 10n ** 9n) / 1e9;
  return {
    tool: NAME,
    token: { address: FLAPJAX, chain: "bsc", symbol: "FLAPJAX", total_supply: supply, price },
    treasury: {
      address: TREASURY,
      flapjax_balance: treasuryBal,
      flapjax_balance_usd: price.usd_per_flapjax != null ? Math.round(treasuryBal * price.usd_per_flapjax * 100) / 100 : null,
      bnb_gas: Number(BigInt(treasuryBnbHex)) / 1e18,
    },
    last_payout: tr.events[0] || null,
    data_source: tr.meta.source,
    checked_at: new Date().toISOString(),
  };
}

function page(url) {
  const e = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(NAME)}</title><style>
body{font-family:ui-monospace,monospace;background:#fdf6e3;color:#3b2f2f;max-width:720px;margin:2rem auto;padding:0 1rem;line-height:1.5}
h1{font-size:1.4rem;margin-bottom:.2rem}.tag{color:#b5651d;font-weight:700}
code{background:#f3e8d3;padding:.1rem .3rem;border-radius:3px}
a{color:#b5651d}table{border-collapse:collapse;margin:.5rem 0}td{padding:0 .5rem 0 0}
</style></head><body>
<h1>🥞 ${e(NAME)}</h1>
<p class="tag">compute is calories · receipts over rockets</p>
<p>Independent community tool for <b>FLAPJAX</b> (BSC <code>${e(FLAPJAX)}</code>) and the on-chain agent treasury (<code>${e(TREASURY)}</code>) that pays the public Bounty Board. Every payout the treasury has ever sent, straight from BSC — no trust required, bring your own node to double-check. No API key needed: it runs on public BSC RPCs.</p>
<table>
<tr><td><code>GET <a href="/health">/health</a></code></td><td>RPC reachability + mode (keyless?)</td></tr>
<tr><td><code>GET <a href="/stats">/stats</a></code></td><td>token price, supply, treasury balances, latest payout</td></tr>
<tr><td><code>GET <a href="/price">/price</a></code></td><td>FLAPJAX spot price, read live from the PancakeSwap V3 FLAPJAX/WBNB 1% pool</td></tr>
<tr><td><code>GET <a href="/treasury-log">/treasury-log</a></code></td><td>last 25 outgoing treasury payouts (public receipt trail)</td></tr>
<tr><td><code>GET /payouts?wallet=0x...</code></td><td><i>did my bounty pay?</i> — all treasury transfers to a wallet</td></tr>
</table>
<p>Example: <code>/payouts?wallet=0x1cEcDFbb8507800e34e07dD4723AbdF8ea07c747</code></p>
<p>Built by <b>Vesper Intel</b> as a working tool-integration for the FlapJax bounty (tool/integration task). Free to use, no key needed. Price: live slot0 read from the Pancake V3 pool; data: public BSC RPCs (+ Dexscreener for the BNB/USD reference); every response carries its own timestamp — the receipt is the product. Source on GitHub: <a href="https://github.com/super-ai-8453/flapjax-desk">super-ai-8453/flapjax-desk</a>.</p>
</body></html>`;
}

const CORS = { "content-type": "application/json", "cache-control": "no-store", "access-control-allow-origin": "*" };

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (request.method !== "GET") return new Response(JSON.stringify({ error: "GET only" }), { status: 405, headers: CORS });
      if (url.pathname === "/" || url.pathname === "/index.html") return new Response(page(url), { headers: { "content-type": "text/html; charset=utf-8" } });
      if (url.pathname === "/health") {
        const latest = await rpc(env, "eth_blockNumber", []);
        return new Response(JSON.stringify({ tool: NAME, status: "ok", rpc_block: parseInt(latest, 16), alchemy_configured: !!env.ALCHEMY_API_KEY, keyless_mode: true, note: "works with no API key via public BSC RPCs", checked_at: new Date().toISOString() }, null, 1), { headers: CORS });
      }
      if (url.pathname === "/stats") return new Response(JSON.stringify(await stats(env), null, 1), { headers: CORS });
      if (url.pathname === "/price")
        return new Response(JSON.stringify({ tool: NAME, price: await poolPrice(env), checked_at: new Date().toISOString() }, null, 1), { headers: CORS });
      if (url.pathname === "/treasury-log") {
        const tr = await transfers(env, null);
        const top = tr.events.slice(0, 25);
        await fillTimestamps(top);
        return new Response(JSON.stringify({ tool: NAME, payouts: top, data_source: tr.meta.source, coverage: { history_block: tr.meta.snapshot_block, complete: tr.meta.source.includes("alchemy") || tr.meta.contiguous !== false }, checked_at: new Date().toISOString() }, null, 1), { headers: CORS });
      }
      if (url.pathname === "/payouts") {
        const wallet = url.searchParams.get("wallet");
        if (!wallet || !/^0x[a-fA-F0-9]{40}$/.test(wallet))
          return new Response(JSON.stringify({ error: "pass ?wallet=0x... (40 hex)" }), { status: 400, headers: CORS });
        const tr = await transfers(env, wallet);
        const events = [...tr.events];
        await fillTimestamps(events);
        return new Response(
          JSON.stringify(
            {
              tool: NAME,
              query: { wallet: wallet.toLowerCase(), from: TREASURY, token: FLAPJAX },
              count: events.length,
              total_flapjax: events.reduce((s, p) => s + (p.amount_flapjax || 0), 0),
              paid: events.length > 0,
              payouts: events,
              data_source: tr.meta.source,
              coverage: {
                history_block: tr.meta.snapshot_block,
                live_delta_from_block: tr.meta.delta_from_block ?? null,
                contiguous: tr.meta.contiguous !== false,
                complete: tr.meta.source.includes("alchemy") || tr.meta.contiguous !== false,
                note: tr.meta.contiguous === false ? "live keyless delta could not reach the snapshot block; any payouts between the snapshot and the live window are not reflected yet" : null,
              },
              checked_at: new Date().toISOString(),
            },
            null,
            1
          ),
          { headers: CORS }
        );
      }
      return new Response(JSON.stringify({ error: "not found", endpoints: ["/health", "/stats", "/price", "/treasury-log", "/payouts?wallet=0x..."] }, null, 1), { status: 404, headers: CORS });
    } catch (e) {
      return new Response(JSON.stringify({ error: String(e && e.message ? e.message : e) }), { status: 500, headers: CORS });
    }
  },
};
